    qs('gcFareMapBtn')?.addEventListener('click', event => {
      flushDeferredFareAdminGuidance();
      openMaps(event);
    });
    qs('gcFareMapsAgain')?.addEventListener('click', event => {
      flushDeferredFareAdminGuidance();
      openMaps(event);
    });
    qs('gcFareCallBtn')?.addEventListener('click', toCall);
